const Entry* Find(uint64_t hash) {
    for (size_t i = 0; i < kEntryCount; ++i) {
        if (kEntries[i].hash == hash) return &kEntries[i];
    }
    return nullptr;
}

const Variant* FindVariant(const Entry& entry, uint32_t spec_constants) {
    const uint32_t wanted = spec_constants & entry.spec_constants_mask;
    for (uint32_t i = 0; i < entry.variant_count; ++i) {
        if (entry.variants[i].spec_constants == wanted) return &entry.variants[i];
    }
    return nullptr;
}

